source('results/C5_Endothelial_GSEA_nominalNicheNet_v1/scripts/common.R');library(nichenetr)
lt<-readRDS(file.path(NN_OUT,'ligand_target_matrix_nsga2r_final.rds'));defs<-fread(file.path(O,'02_nominal_response_genesets/frozen_genesets.tsv'));g<-defs[program=='Set_B',gene];a<-fread(file.path(O,'03_nominal_NicheNet/checkpoints/Set_B.tsv'));top<-a[rank<=10,test_ligand]
# Influence diagnostics only: one largest prior-weight target per frozen Set B top10 ligand.
# Fixed rule before rerunning activity; never select deletion by improvement.
sel<-rbindlist(lapply(top,function(l){v<-lt[g,l];ord<-order(-v,names(v));data.table(ligand=l,gene=names(v)[ord[1]],prior_weight=max(v),max_target_weight_share=max(v)/sum(v),top5_weight_share=sum(sort(v,decreasing=TRUE)[1:5])/sum(v))}));w(sel,'04_rank_sensitivity/target_influence_prespecified_selection.tsv')
writeLines('Diagnostic rule: remove each unique largest prior-weight Set B target of each frozen Set B top10 ligand, one at a time. No re-selection or optimization. Prior-weight concentration is not a direct decomposition of activity.',file.path(O,'04_rank_sensitivity/target_influence_rule.txt'))
res<-list();for(gg in unique(sel$gene)){fn<-file.path(O,'03_nominal_NicheNet/checkpoints',paste0('DROP_TARGET_',gg,'.tsv'));if(file.exists(fn))z<-fread(fn) else{z<-as.data.table(predict_ligand_activities(setdiff(g,gg),bg$gene,lt,ligs));setorder(z,-aupr_corrected,-pearson,test_ligand);z[,`:=`(rank=seq_len(.N),removed_gene=gg)];fwrite(z,fn,sep='\t')};res[[gg]]<-z;cat('DROP_TARGET',gg,'\n');flush.console()};w(rbindlist(res),'04_rank_sensitivity/target_influence_activities.tsv');cat('TARGET_INFLUENCE_COMPLETE\n')
